namespace HakutaiKagami.Core.Contracts;
public enum SecurityAction { Assign, Observe }
public sealed record SecurityInput(EntityId Id,SecurityAction Action,EntityId Site,EntityId? Guard=null);
public sealed record SecurityFact(long At,int Bandits,int Guards,long UnprotectedSeconds,string Reaction);
public sealed record SecurityOrder(SecurityInput Input,EntityId Actor,long At,long Revision,long Until,long Paid,SecurityFact? Fact);
public static class LocalSecurity
{
 public const string Policy="actual-local-guards-known-security-market-restraint-v2";
 public static bool Enabled(ContractWorld w)=>w.NewGame?.BanditPolicy==Policy;
 internal static SecurityOrder[] Orders(ContractWorld w)=>w.Bandits?.Security??[];
 static bool Before(SecurityOrder o,long at,long rev)=>o.At<at||o.At==at&&o.Revision<rev;
 static void Need(bool ok,string why){if(!ok)throw new InvalidDataException(why);}
 public static bool OwnIdUsed(ContractWorld w,EntityId id)=>Orders(w).Any(o=>o.Input.Id==id);
 public static bool Reserved(ContractWorld w,EntityId actor,long at,long rev)=>Orders(w).Any(o=>o.Input.Action==SecurityAction.Assign&&o.Input.Guard==actor&&Before(o,at,rev)&&at<o.Until);
 public static int BanditsAt(ContractWorld w,EntityId site,long at)=>Enabled(w)&&BanditEncounter.Camps.Contains(site)&&!(w.Bandits?.Encounters.Any(e=>e.Site==site&&e.Phase=="賊が敗走"&&e.LastAt<=at)??false)?3:0;
 public static int GuardsAt(ContractWorld w,EntityId site,long at,long rev)=>Orders(w).Where(o=>o.Input.Action==SecurityAction.Assign&&o.Input.Site==site&&Before(o,at,rev)&&at<o.Until&&TransportWork.At(w,o.Input.Guard!.Value,site,at,rev,true)).Select(o=>o.Input.Guard).Distinct().Count();
 public static bool Protected(ContractWorld w,EntityId site,long at,long rev)=>Enabled(w)&&GuardsAt(w,site,at,rev)>=Math.Max(1,BanditsAt(w,site,at));
 public static long Unprotected(ContractWorld w,EntityId site,long at,long rev){using var _ccRev=ControlContext.At(rev);if(!Enabled(w)||!BanditEncounter.Camps.Contains(site))return 0;var points=Orders(w).Where(o=>o.Input.Site==site&&Before(o,at,rev)).SelectMany(o=>new[]{o.At,o.Until}).Concat((w.Bandits?.Encounters??[]).Where(e=>e.Site==site&&e.Phase=="賊が敗走").Select(e=>e.LastAt)).Append(0).Append(at).Where(t=>t>=0&&t<=at).Distinct().Order().ToArray();long n=0;for(int k=0;k<points.Length-1;k++){long t=points[k];if(BanditsAt(w,site,t)>0&&!Protected(w,site,t,long.MaxValue))n+=points[k+1]-t; }return n;}
 public static bool MarketAvoided(ContractWorld w,EntityId site,long at,long rev)=>Enabled(w)&&BanditsAt(w,site,at)>0&&!Protected(w,site,at,rev)&&Unprotected(w,site,at,rev)>=3*86400;
 public static string Reaction(ContractWorld w,EntityId site,long at,long rev)=>!Enabled(w)?"":BanditEncounter.Camps.Contains(site)&&BanditsAt(w,site,at)==0?"賊の敗走を現地で確認し、討伐を評価しています。":Protected(w,site,at,rev)?"警固の実在を確認し、通行を頼りにしています。":MarketAvoided(w,site,at,rev)?"賊が残り警固のない日が三日以上あります。商人は新規取引を見合わせ、村は警固を求めています。":"現地の賊と警固を確かめています。";
 public static long Net(ContractWorld w,EntityId wallet,long at,long rev)=>Orders(w).Where(o=>Before(o,at,rev)).Sum(o=>(NewGameWork.Wallet(o.Actor)==wallet?-o.Paid:0)+(o.Input.Guard is {} g&&NewGameWork.Wallet(g)==wallet?o.Paid:0));
 public static EntityId[] Candidates(ContractWorld w,EntityId site)=>!Enabled(w)?[]:w.Characters.Where(c=>c.Id!=w.PlayerControl&&c.Life==LifeState.Adult&&c.WillObey&&HouseholdService.BondsAt(w,w.ElapsedSeconds,w.CommitSequence+1).Any(b=>b.Subject==c.Id&&b.Target==w.PlayerControl&&b.From<=w.ElapsedSeconds&&w.ElapsedSeconds<b.Until)&&TransportWork.At(w,c.Id,site,w.ElapsedSeconds,w.CommitSequence+1,true)&&!PersonalCompanions.Occupied(w,c.Id,w.ElapsedSeconds,w.CommitSequence)&&!NpcArmies.CommanderBusyAt(w,c.Id,w.ElapsedSeconds,w.CommitSequence+1)).Select(c=>c.Id).ToArray();
 static SecurityFact Fact(ContractWorld w,EntityId site,long at,long rev)=>new(at,BanditsAt(w,site,at),GuardsAt(w,site,at,rev),Unprotected(w,site,at,rev),Reaction(w,site,at,rev));
 public static SecurityFact? Known(ContractWorld w,EntityId site)=>Orders(w).LastOrDefault(o=>o.Input.Site==site&&o.Actor==w.PlayerControl&&o.Input.Action==SecurityAction.Observe)?.Fact;
 static void Check(ContractWorld w,SecurityOrder o){var i=o.Input;Need(!FactionStances.OtherIdUsed(w,i.Id,includeSecurity:false)&&!FactionStances.OwnIdUsed(w,i.Id),"別の操作の原本IDです");Need(Enabled(w)&&EntityId.IsValid(i.Id.Value)&&Enum.IsDefined(i.Action)&&o.Actor==ControlSuccession.PlayerAtRevision(w,o.Revision)&&TransportWork.At(w,o.Actor,i.Site,o.At,o.Revision,true),"本人の現地で警固を相談してください");if(i.Action==SecurityAction.Observe){Need(i.Guard==null&&o.Paid==0&&o.Until==o.At&&o.Fact==Fact(w,i.Site,o.At,o.Revision),"現地確認の時点・内容が違います");return;}Need(i.Guard is {} g&&g!=o.Actor&&o.Paid==60&&o.Until==o.At+3*86400&&o.Fact==null,"三日間・私財60文の警固合意です");var guard=i.Guard!.Value;Need(w.Characters.Any(c=>c.Id==guard&&c.WillObey&&c.Life==LifeState.Adult)&&HouseholdService.BondsAt(w,o.At,o.Revision).Any(b=>b.Subject==guard&&b.Target==o.Actor&&b.From<=o.At&&o.At<b.Until)&&TransportWork.At(w,guard,i.Site,o.At,o.Revision,true),"現地の直属家臣本人の合意がありません");Need(!Reserved(w,guard,o.At,o.Revision)&&!GuardJobs.Reserved(w,guard,o.At,o.Revision)&&!NpcArmies.CommanderBusyAt(w,guard,o.At,o.Revision)&&TransportWork.WalletBefore(w,o.Actor,o.At,o.Revision)>=60,"任務の重複か手当の不足です");}
 internal static void Apply(ContractWorld w,SecurityInput i){if(i.Action==SecurityAction.Assign)Need(Candidates(w,i.Site).Contains(i.Guard??default),"他の仕事の空いた直属家臣へ相談してください");var o=new SecurityOrder(i,w.PlayerControl,w.ElapsedSeconds,w.CommitSequence,i.Action==SecurityAction.Assign?w.ElapsedSeconds+3*86400:w.ElapsedSeconds,i.Action==SecurityAction.Assign?60:0,i.Action==SecurityAction.Observe?Fact(w,i.Site,w.ElapsedSeconds,w.CommitSequence):null);Check(w,o);w.Bandits??=new(1,BanditEncounter.Policy,[],[]);w.Bandits=w.Bandits with{Security=[..Orders(w),o]};}
 public static void Validate(ContractWorld w,ContractWorld? prior){var os=Orders(w);Need(Enabled(w)||os.Length==0,"旧世界へ警固を追加できません");if(prior!=null)Need(os.Take(Orders(prior).Length).SequenceEqual(Orders(prior)),"警固の原本を変更できません");long at=0,rev=0;var ids=new HashSet<EntityId>();foreach(var o in os){Need(o.At>=at&&o.At<=w.ElapsedSeconds&&o.Revision>rev&&o.Revision<=w.CommitSequence&&ids.Add(o.Input.Id),"警固の時点・重複が不正です");Check(w,o);at=o.At;rev=o.Revision;}}
}
public sealed partial class WorldSession
{
 public CommandResult ManageSecurity(SecurityInput i,long revision){using var _ccRev=ControlContext.At(revision);lock(gate){var old=LocalSecurity.Orders(state).SingleOrDefault(o=>o.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"受付済みです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");if(NewGameWork.OwnIdUsed(state,i.Id)||state.Requests.Any(r=>r.Id==i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"使用済みの原本です");try{Change(w=>LocalSecurity.Apply(w,i));return new(ResultCode.Accepted,i.Id,state.CommitSequence,"現地の警固と確認を記録しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
